def preserve_price_choices(apps, schema_editor):
    PoolModel=apps.get_model('aihub','PoolModel');Price=apps.get_model('aihub','PriceVersion')
    for model in PoolModel.objects.using(schema_editor.connection.alias).all().iterator():
        price=Price.objects.using(schema_editor.connection.alias).filter(model_id=model.pk).order_by('-effective_from','-pk').first()
        if price and not price.source.startswith('自动读取：') and not model.price_feed_url:
            PoolModel.objects.using(schema_editor.connection.alias).filter(pk=model.pk).update(price_mode='manual')


